/** Activation intents — declared, translated by adapters (0001 §3.8). */
export const service = (name, user = true, trigger = "post_activate") => ({ kind: "service", trigger, name, user });
export const fonts = (trigger = "post_link") => ({
    kind: "fonts",
    trigger,
});
export const desktopEntry = (trigger = "post_link") => ({
    kind: "desktop_entry",
    trigger,
});
/** Escape hatch — flagged, shown by `plan`. */
export const customHook = (script, trigger = "post_activate") => ({
    kind: "custom_shell",
    trigger,
    script,
});
